// test_12k_symbol_resolution.rs - Test suite for 12k recursive symbol resolution
// Generated by step4_bootstrap - 12k Symbol Resolution

use split_decls_genesis::{
    mkfast_symbol_resolution, find_rust_files_in_dependency_fast,
    resolve_symbols_recursively_fast, extract_all_symbols_from_file_fast,
    get_rustc_dependencies, Symbol, SymbolResolution, analyze_and_display_function_body,
    resolve_qualified_dependency
};
use std::collections::HashMap;

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing 12k recursive symbol resolution...");
    
    // Run the fast 12k symbol resolution using proven syn patterns
    let resolution: SymbolResolution = mkfast_symbol_resolution!(12000);
    
    println!("\n📊 12K SYMBOL RESOLUTION RESULTS:");
    println!("  🎯 Target: 12,000 symbols");
    println!("  🔧 Resolved: {} symbols", resolution.total_resolved);
    println!("  📈 Progress: {:.1}% of target", 
             (resolution.total_resolved as f64 / 12000.0) * 100.0);
    println!("  🌊 Max depth: {}", resolution.max_depth);
    println!("  🌳 Unique symbols: {}", resolution.resolved_symbols.len());
    
    // Analyze symbol types
    let mut type_counts = HashMap::new();
    for symbol in resolution.resolved_symbols.values() {
        *type_counts.entry(&symbol.symbol_type).or_insert(0) += 1;
    }
    
    println!("\n📈 Symbol types breakdown:");
    let mut sorted_types: Vec<_> = type_counts.iter().collect();
    sorted_types.sort_by(|a, b| b.1.cmp(a.1));
    
    for (symbol_type, count) in sorted_types {
        let icon = match symbol_type.as_str() {
            "fn" => "🔧",
            "struct" => "🏗️",
            "enum" => "📋",
            "trait" => "🎯",
            "impl" => "⚙️",
            "type" => "📝",
            "const" => "🔒",
            "static" => "📌",
            _ => "📦"
        };
        println!("  {} {}: {}", icon, symbol_type, count);
    }
    
    // Analyze crate distribution
    let mut crate_counts = HashMap::new();
    for symbol in resolution.resolved_symbols.values() {
        *crate_counts.entry(&symbol.crate_name).or_insert(0) += 1;
    }
    
    println!("\n📦 Crate distribution:");
    let mut sorted_crates: Vec<_> = crate_counts.iter().collect();
    sorted_crates.sort_by(|a, b| b.1.cmp(a.1));
    
    for (crate_name, count) in sorted_crates.iter().take(10) {
        println!("  📦 {}: {} symbols", crate_name, count);
    }
    
    // Show resolution depth analysis
    println!("\n🌊 Resolution depth analysis:");
    let mut depth_symbols = HashMap::new();
    
    // Simulate depth tracking (simplified)
    for (i, symbol_name) in resolution.resolution_order.iter().enumerate() {
        let depth = (i / 100).min(10); // Approximate depth
        *depth_symbols.entry(depth).or_insert(0) += 1;
    }
    
    for depth in 0..=resolution.max_depth.min(10) {
        if let Some(count) = depth_symbols.get(&depth) {
            let bar = "█".repeat((count / 10).max(1).min(50));
            println!("  Depth {}: {} symbols {}", depth, count, bar);
        }
    }
    
    // Show sample resolved symbols
    println!("\n📝 Sample resolved symbols:");
    for (i, symbol_name) in resolution.resolution_order.iter().take(15).enumerate() {
        if let Some(symbol) = resolution.resolved_symbols.get(symbol_name) {
            println!("  {}. {} ({}) from {} - {} deps", 
                     i+1, symbol.name, symbol.symbol_type, 
                     symbol.crate_name, symbol.dependencies.len());
        }
    }
    
    // Success criteria
    if resolution.total_resolved >= 12000 {
        println!("\n🎉 SUCCESS: 12k symbol resolution target achieved!");
        println!("   🔧 Resolved {} symbols across {} crates", 
                 resolution.total_resolved, crate_counts.len());
    } else if resolution.total_resolved >= 6000 {
        println!("\n⚡ GOOD: Substantial symbol resolution achieved!");
        println!("   🔧 Resolved {} symbols, {}% of target", 
                 resolution.total_resolved, 
                 (resolution.total_resolved * 100) / 12000);
    } else {
        println!("\n⚠️  Partial resolution. Need to expand symbol extraction.");
    }
    
    println!("\n🎉 12k symbol resolution test complete!");
    Ok(())
}
